#!/usr/bin/env bash
# Autogenerated test: runs inside a container built from each compatibility image with blender installed with default
# options, as the image's remote user, and also as root through sudo when the remote user is not root.
set -euo pipefail

# shellcheck source=/dev/null
source dev-container-features-test-lib
# shellcheck source=/dev/null
source "$(dirname "$0")/helpers.sh"

# Succeeds when a first start finds online access off, per-user directories under HOME and not created yet, and only
# the add-ons bundled with the release.
fresh_user_defaults() {
  cat >"${SCRATCH}/fresh.py" <<'PY'
import os
import addon_utils
import bpy

home = os.path.expanduser("~")
user = bpy.utils.resource_path("USER")
problems = []
if bpy.app.online_access:
    problems.append("online access is on")
if not user.startswith(home + os.sep):
    problems.append("user directory %s is outside %s" % (user, home))
if os.path.exists(user):
    problems.append("user directory %s already exists" % user)
foreign = [m.__file__ for m in addon_utils.modules() if not m.__file__.startswith("/opt/blender/")]
if foreign:
    problems.append("add-ons outside the release: %s" % foreign)
if problems:
    print("PROBLEMS", problems)
    raise SystemExit(3)
PY
  timeout "${LIMIT}" blender -b --python-exit-code 1 --python "${SCRATCH}/fresh.py" >"${SCRATCH}/fresh.log" 2>&1 || {
    cat "${SCRATCH}/fresh.log" >&2
    return 1
  }
}

# Succeeds when a process started from a Blender script sees the caller's LD_LIBRARY_PATH unchanged.
child_sees_caller_library_path() {
  cat >"${SCRATCH}/child.py" <<'PY'
import subprocess

seen = subprocess.run(["sh", "-c", 'printf %s "$LD_LIBRARY_PATH"'], capture_output=True, text=True).stdout
raise SystemExit(0 if seen == "/caller/lib" else 3)
PY
  LD_LIBRARY_PATH=/caller/lib timeout "${LIMIT}" blender -b --factory-startup --python-exit-code 1 \
    --python "${SCRATCH}/child.py" >"${SCRATCH}/child.log" 2>&1 || {
    cat "${SCRATCH}/child.log" >&2
    return 1
  }
}

before="$(tree_manifest)"
latest="$(newest_release)"

check "a first start keeps Blender's defaults" fresh_user_defaults
check "the feature sets no Blender environment variable" bash -c '! env | grep -q "^BLENDER_"'
check "no display server is installed" bash -c '! command -v Xorg && ! command -v Xvfb'
check "no Vulkan driver is installed" bash -c '! compgen -G "/usr/share/vulkan/icd.d/*.json"'
check "blender reports the newest release on download.blender.org" reports_release "${latest}"
check "the marker records the installed release" test "$(cat "${TREE}/.devcontainer-feature-blender")" = "${latest}"
check "/usr/local/bin/blender links to the executable" link_targets_executable
check "the installation belongs to root and only root can write it" tree_is_root_only
check "Cycles renders a frame in background mode" renders_frame CYCLES
check "Workbench renders a frame in background mode" renders_frame BLENDER_WORKBENCH
check "EEVEE renders a frame in background mode" renders_frame BLENDER_EEVEE
check "a script's success or failure sets the exit status" script_status_follows_script
check "a process a script starts sees the caller's LD_LIBRARY_PATH" child_sees_caller_library_path
make_extension "${SCRATCH}/probe_ext" probe_ext
check "an extension source validates" validates_extension "${SCRATCH}/probe_ext"
if [[ "$(id -u)" != 0 ]]; then
  check "root reports the newest release" reports_release "${latest}" sudo -n
  check "root renders a frame with Cycles" renders_frame CYCLES sudo -n
  check "root renders a frame with EEVEE" renders_frame BLENDER_EEVEE sudo -n
fi
check "running Blender leaves the installation tree unchanged" test "$(tree_manifest)" = "${before}"

reportResults
